/**
 * Where uploaded files (lesson media, rubric PDFs, learners' attachments, the navigation video) live.
 *
 *  - "disk":     a folder (UPLOAD_DIR). Used when there is no DATABASE_URL, or when UPLOAD_DIR is set
 *                explicitly (a persistent disk on a VPS or a host volume).
 *  - "database": PostgreSQL, in 1 MB pieces. Used when DATABASE_URL is set and UPLOAD_DIR is not, so
 *                files survive on hosts whose disk is wiped on every restart.
 *
 * Every file is addressed by its URL, "/uploads/<name>", and the name is always generated by the
 * server (never taken from the uploaded file), so it is safe to use as a key or a file name.
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import type { Request, Response } from 'express';
import { DATA_DIR, ROOT, pgPool, storageMode } from './db';

export type FileMode = 'disk' | 'database';
export const fileMode: FileMode = storageMode === 'postgres' && !process.env.UPLOAD_DIR ? 'database' : 'disk';

/**
 * The uploads folder (disk mode). With DATA_DIR set, uploads sit next to the data by default,
 * so one persistent folder holds everything.
 */
export const UPLOAD_DIR = process.env.UPLOAD_DIR
  ? path.resolve(process.env.UPLOAD_DIR)
  : process.env.DATA_DIR
    ? path.join(DATA_DIR, 'uploads')
    : path.join(ROOT, 'uploads');

/** Where multer writes an upload first: the final folder on disk, or a scratch folder before it moves into the database. */
export const UPLOAD_TMP = fileMode === 'disk' ? UPLOAD_DIR : path.join(os.tmpdir(), 'usaii-lms-uploads');
fs.mkdirSync(UPLOAD_TMP, { recursive: true });
if (fileMode === 'disk') fs.mkdirSync(UPLOAD_DIR, { recursive: true });

const CHUNK = 1024 * 1024;

/** Media, images and PDFs open in the browser; anything else downloads (and can never run as a page). */
export const INLINE_UPLOAD = /\.(mp4|m4v|mov|webm|ogv|mp3|m4a|wav|ogg|aac|flac|png|jpe?g|gif|webp|avif|pdf)$/i;

const MIME: Record<string, string> = {
  '.mp4': 'video/mp4', '.m4v': 'video/mp4', '.mov': 'video/quicktime', '.webm': 'video/webm', '.ogv': 'video/ogg',
  '.mp3': 'audio/mpeg', '.m4a': 'audio/mp4', '.wav': 'audio/wav', '.ogg': 'audio/ogg', '.aac': 'audio/aac', '.flac': 'audio/flac',
  '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.gif': 'image/gif', '.webp': 'image/webp', '.avif': 'image/avif',
  '.pdf': 'application/pdf', '.doc': 'application/msword', '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  '.xls': 'application/vnd.ms-excel', '.xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  '.ppt': 'application/vnd.ms-powerpoint', '.pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  '.csv': 'text/csv', '.txt': 'text/plain', '.md': 'text/markdown', '.vtt': 'text/vtt', '.srt': 'text/plain', '.zip': 'application/zip',
};
export const mimeFor = (name: string) => MIME[path.extname(name).toLowerCase()] ?? 'application/octet-stream';

/** The stored name for a "/uploads/<name>" URL, or null (blocks path tricks). */
export function nameFromUrl(url: string): string | null {
  if (typeof url !== 'string' || !url.startsWith('/uploads/')) return null;
  const name = url.slice('/uploads/'.length);
  if (!name || name !== path.basename(name) || name.startsWith('.') || !/^[A-Za-z0-9._-]+$/.test(name)) return null;
  return name;
}

const diskPath = (name: string) => path.join(UPLOAD_DIR, name);

/** Take a file multer has just written and keep it for good. */
export async function keepUpload(tmpPath: string, name: string): Promise<void> {
  if (fileMode === 'disk') return; // multer already wrote it into UPLOAD_DIR
  try {
    const size = (await fs.promises.stat(tmpPath)).size;
    const fh = await fs.promises.open(tmpPath, 'r');
    const client = await pgPool().connect();
    try {
      await client.query('BEGIN');
      await client.query('DELETE FROM lms_file_chunks WHERE name = $1', [name]);
      const buf = Buffer.alloc(CHUNK);
      for (let n = 0, pos = 0; pos < size; n += 1, pos += CHUNK) {
        const { bytesRead } = await fh.read(buf, 0, Math.min(CHUNK, size - pos), pos);
        await client.query('INSERT INTO lms_file_chunks (name, n, data) VALUES ($1, $2, $3)', [name, n, Buffer.from(buf.subarray(0, bytesRead))]);
      }
      await client.query(
        'INSERT INTO lms_files (name, size, mime, chunk_size) VALUES ($1, $2, $3, $4) ON CONFLICT (name) DO UPDATE SET size = EXCLUDED.size, mime = EXCLUDED.mime, chunk_size = EXCLUDED.chunk_size',
        [name, size, mimeFor(name), CHUNK],
      );
      await client.query('COMMIT');
    } catch (e) {
      await client.query('ROLLBACK').catch(() => undefined);
      throw e;
    } finally {
      client.release();
      await fh.close();
    }
  } finally {
    await fs.promises.unlink(tmpPath).catch(() => undefined);
  }
}

export async function fileInfo(name: string): Promise<{ size: number; mime: string; chunkSize: number } | null> {
  if (fileMode === 'disk') {
    try {
      const st = await fs.promises.stat(diskPath(name));
      return st.isFile() ? { size: st.size, mime: mimeFor(name), chunkSize: CHUNK } : null;
    } catch {
      return null;
    }
  }
  const r = await pgPool().query<{ size: string; mime: string; chunk_size: number }>('SELECT size, mime, chunk_size FROM lms_files WHERE name = $1', [name]);
  return r.rows[0] ? { size: Number(r.rows[0].size), mime: r.rows[0].mime, chunkSize: r.rows[0].chunk_size } : null;
}

export async function fileExists(url: string): Promise<boolean> {
  const name = nameFromUrl(url);
  return !!name && !!(await fileInfo(name));
}

/** The whole file in memory (small files only: rubric PDFs, caption files). Null if missing or too large. */
export async function readUpload(url: string, maxBytes = 25 * 1024 * 1024): Promise<Buffer | null> {
  const name = nameFromUrl(url);
  if (!name) return null;
  const info = await fileInfo(name);
  if (!info || info.size > maxBytes) return null;
  if (fileMode === 'disk') return fs.promises.readFile(diskPath(name));
  const r = await pgPool().query<{ data: Buffer }>('SELECT data FROM lms_file_chunks WHERE name = $1 ORDER BY n', [name]);
  return Buffer.concat(r.rows.map((x) => x.data));
}

export async function deleteUpload(url: string): Promise<void> {
  const name = nameFromUrl(url);
  if (!name) return;
  if (fileMode === 'disk') {
    await fs.promises.unlink(diskPath(name)).catch(() => undefined);
    return;
  }
  await pgPool().query('DELETE FROM lms_files WHERE name = $1', [name]);
  await pgPool().query('DELETE FROM lms_file_chunks WHERE name = $1', [name]);
}

/** Run `fn` with the file on the local disk (for tools that need a path, such as a transcription upload). */
export async function withLocalFile<T>(url: string, fn: (filePath: string) => Promise<T>): Promise<T | null> {
  const name = nameFromUrl(url);
  if (!name || !(await fileInfo(name))) return null;
  if (fileMode === 'disk') return fn(diskPath(name));
  const tmp = path.join(UPLOAD_TMP, `copy-${Date.now()}-${name}`);
  const out = fs.createWriteStream(tmp);
  try {
    for (let n = 0; ; n += 8) {
      const r = await pgPool().query<{ data: Buffer }>('SELECT data FROM lms_file_chunks WHERE name = $1 AND n >= $2 AND n < $3 ORDER BY n', [name, n, n + 8]);
      if (!r.rows.length) break;
      for (const row of r.rows) if (!out.write(row.data)) await new Promise<void>((ok) => out.once('drain', () => ok()));
    }
    await new Promise<void>((ok, bad) => out.end((e?: Error | null) => (e ? bad(e) : ok())));
    return await fn(tmp);
  } finally {
    out.destroy();
    await fs.promises.unlink(tmp).catch(() => undefined);
  }
}

/** Remove half-finished uploads left by a crash (database mode). */
export async function cleanUpFileStore(): Promise<void> {
  if (fileMode !== 'database') return;
  await pgPool().query('DELETE FROM lms_file_chunks c WHERE NOT EXISTS (SELECT 1 FROM lms_files f WHERE f.name = c.name)');
  for (const f of await fs.promises.readdir(UPLOAD_TMP).catch(() => [] as string[])) await fs.promises.unlink(path.join(UPLOAD_TMP, f)).catch(() => undefined);
}

/**
 * Serve one stored file from the database, with Range support so videos can seek.
 * (In disk mode express.static does this; see server/index.ts.) Access is checked before this runs.
 */
export async function serveFromDatabase(req: Request, res: Response): Promise<void> {
  let name: string | null = null;
  try {
    name = nameFromUrl(`/uploads${decodeURIComponent(req.path)}`);
  } catch {
    name = null;
  }
  const info = name ? await fileInfo(name) : null;
  if (!name || !info) {
    res.status(404).type('text/plain').send('File not found.');
    return;
  }
  const { size, chunkSize } = info;
  res.setHeader('Content-Type', info.mime);
  res.setHeader('Accept-Ranges', 'bytes');
  if (!INLINE_UPLOAD.test(name)) {
    res.setHeader('Content-Disposition', 'attachment');
    res.setHeader('Content-Security-Policy', "sandbox; default-src 'none'");
  }
  let start = 0;
  let end = size - 1;
  const range = req.headers.range;
  if (range) {
    const m = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
    if (!m || (!m[1] && !m[2])) {
      res.status(416).setHeader('Content-Range', `bytes */${size}`).end();
      return;
    }
    if (m[1]) {
      start = Number(m[1]);
      end = m[2] ? Math.min(Number(m[2]), size - 1) : size - 1;
    } else {
      start = Math.max(0, size - Number(m[2]));
    }
    if (start >= size || start > end) {
      res.status(416).setHeader('Content-Range', `bytes */${size}`).end();
      return;
    }
    // Answer an open-ended video request in pieces; the browser asks for the rest as it plays.
    end = Math.min(end, start + 8 * chunkSize - 1);
    res.status(206).setHeader('Content-Range', `bytes ${start}-${end}/${size}`);
  }
  res.setHeader('Content-Length', String(end - start + 1));
  if (req.method === 'HEAD' || size === 0) {
    res.end();
    return;
  }
  let closed = false;
  req.on('close', () => (closed = true));
  const first = Math.floor(start / chunkSize);
  const last = Math.floor(end / chunkSize);
  for (let n = first; n <= last && !closed; n += 4) {
    const r = await pgPool().query<{ n: number; data: Buffer }>('SELECT n, data FROM lms_file_chunks WHERE name = $1 AND n >= $2 AND n <= $3 ORDER BY n', [name, n, Math.min(last, n + 3)]);
    for (const row of r.rows) {
      const base = row.n * chunkSize;
      const from = Math.max(0, start - base);
      const to = Math.min(row.data.length, end - base + 1);
      if (to > from && !res.write(row.data.subarray(from, to))) await new Promise<void>((ok) => res.once('drain', () => ok()));
      if (closed) break;
    }
  }
  res.end();
}
